Here is the problem description:
<problem_description>
All bus tickets in Berland have their numbers. A number consists of $$$n$$$ digits ($$$n$$$ is even). Only $$$k$$$ decimal digits $$$d_1, d_2, \dots, d_k$$$ can be used to form ticket numbers. If $$$0$$$ is among these digits, then numbers may have leading zeroes. For example, if $$$n = 4$$$ and only digits $$$0$$$ and $$$4$$$ can be used, then $$$0000$$$, $$$4004$$$, $$$4440$$$ are valid ticket numbers, and $$$0002$$$, $$$00$$$, $$$44443$$$ are not.A ticket is lucky if the sum of first $$$n / 2$$$ digits is equal to the sum of remaining $$$n / 2$$$ digits. Calculate the number of different lucky tickets in Berland. Since the answer may be big, print it modulo $$$998244353$$$.
</problem_description>

Here is the Java 8 code you have to repair:
<original_code>
import java.util.*;
import java.io.*;

public class p1096g_v3 {
    static final long MOD = 998244353;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        long[] base = new long[10];
        for (int i = 0; i < k; i++) {
            base[sc.nextInt()] = 1;
        }
        long[] result = fastPow(base, n / 2);
        long ans = 0;
        for (long val : result) {
            ans = (ans + val * val) % MOD;
        }
        System.out.println(ans);
    }

    static long[] fastPow(long[] base, long exp) {
        if (exp == 1) return base;
        if ((exp & 1) == 1) {
            return FFT.multiplyPrecise(base, fastPow(base, exp - 1));
        }
        long[] half = fastPow(base, exp >> 1);
        return FFT.multiplyPrecise(half, half);
    }

    static class FFT {
        static final int MAX_K = 23;
        static final int MAX_N = 1 << MAX_K;
        static double[] wR = new double[MAX_N];
        static double[] wI = new double[MAX_N];
        static double[] aR = new double[MAX_N];
        static double[] aI = new double[MAX_N];
        static int n, k, lastK = -1;
        static int[] rev = new int[MAX_N];

        static void init(int size) {
            n = size;
            k = 0;
            while ((1 << k) < n) k++;
            if (lastK != k) {
                lastK = k;
                rev[0] = 0;
                for (int i = 1, g = 0; i < n; i++) {
                    if ((i & (i - 1)) == 0) g++;
                    rev[i] = rev[i ^ (1 << g)] ^ (1 << (k - 1 - g));
                }
                wR[1] = 1;
                wI[1] = 0;
                for (int t = 0; t < k - 1; t++) {
                    double angle = Math.PI / n * (1 << (k - 1 - t));
                    double cosVal = Math.cos(angle);
                    double sinVal = Math.sin(angle);
                    int step = 1 << t;
                    for (int j = step, idx = step << 1; j < step << 1; j++, idx += 2) {
                        wR[idx] = wR[j];
                        wI[idx] = wI[j];
                        wR[idx + 1] = wR[j] * cosVal - wI[j] * sinVal;
                        wI[idx + 1] = wR[j] * sinVal + wI[j] * cosVal;
                    }
                }
            }
        }

        static void fft(boolean inv) {
            for (int i = 0; i < n; i++) {
                int j = rev[i];
                if (i < j) {
                    double tmp = aR[i];
                    aR[i] = aR[j];
                    aR[j] = tmp;
                    tmp = aI[i];
                    aI[i] = aI[j];
                    aI[j] = tmp;
                }
            }
            if (inv) {
                for (int i = 0; i < n; i++) aI[i] = -aI[i];
            }
            for (int len = 1; len < n; len <<= 1) {
                for (int i = 0; i < n; i += len << 1) {
                    for (int j = 0; j < len; j++) {
                        int idx = len + j;
                        double tr = aR[i + len + j] * wR[idx] - aI[i + len + j] * wI[idx];
                        double ti = aR[i + len + j] * wI[idx] + aI[i + len + j] * wR[idx];
                        aR[i + len + j] = aR[i + j] - tr;
                        aI[i + len + j] = aI[i + j] - ti;
                        aR[i + j] += tr;
                        aI[i + j] += ti;
                    }
                }
            }
        }

        static long[] multiply(long[] a, long[] b) {
            int lenA = a.length, lenB = b.length;
            int size = 1;
            while (size < lenA + lenB - 1) size <<= 1;
            init(size);
            for (int i = 0; i < size; i++) {
                aR[i] = i < lenA ? a[i] : 0;
                aI[i] = i < lenB ? b[i] : 0;
            }
            fft(false);
            aR[size] = aR[0];
            aI[size] = aI[0];
            double factor = -1.0 / (4.0 * size);
            for (int i = 0; i <= size - i; i++) {
                double r1 = aR[i], im1 = aI[i];
                double r2 = aR[size - i], im2 = aI[size - i];
                double real = r1 * r1 - im1 * im1 - (r2 * r2 - im2 * im2);
                double imag = 2 * r1 * im1 + 2 * r2 * im2;
                aR[i] = -imag * factor;
                aI[i] = real * factor;
                aR[size - i] = aR[i];
                aI[size - i] = -aI[i];
            }
            fft(true);
            long[] res = new long[lenA + lenB - 1];
            for (int i = 0; i < res.length; i++) res[i] = Math.round(aR[i]) % MOD;
            return res;
        }

        static long[] multiplyPrecise(long[] x, long[] y) {
            long base = (long) Math.sqrt(MOD);
            long[] xl = new long[x.length];
            long[] xh = new long[x.length];
            long[] yl = new long[y.length];
            long[] yh = new long[y.length];
            for (int i = 0; i < x.length; i++) {
                xl[i] = x[i] % base;
                xh[i] = x[i] / base;
            }
            for (int i = 0; i < y.length; i++) {
                yl[i] = y[i] % base;
                yh[i] = y[i] / base;
            }
            long[] p11 = multiply(xl, yl);
            long[] p12 = multiply(xl, yh);
            long[] p21 = multiply(xh, yl);
            long[] p22 = multiply(xh, yh);
            long[] res = new long[p11.length];
            for (int i = 0; i < res.length; i++) {
                long term1 = (base * base % MOD) * p22[i] % MOD;
                long term2 = base * ((p12[i] + p21[i]) % MOD) % MOD;
                res[i] = (term1 + term2 + p11[i]) % MOD;
            }
            return res;
        }
    }
}
